import { test, expect } from '@playwright/test';

test.describe('CSV Import Functionality', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/import');
  });

  test('should display the import form', async ({ page }) => {
    const importForm = page.getByRole('form', { name: /import records/i });
    await expect(importForm).toBeVisible();
  });

  test('should successfully import records from a CSV file', async ({ page }) => {
    const filePath = 'path/to/your/test.csv';
    await page.getByLabel('Choose CSV file').setInputFiles(filePath);
    await page.getByRole('button', { name: /import/i }).click();

    const successMessage = page.getByText(/records imported successfully/i);
    await expect(successMessage).toBeVisible();
  });
});
